    def add_operation(op, pos):
        operations.append(f"{op}{pos}")

    def increase_adjacent(pos):
        add_operation('+', pos)
        numbers[pos - 1] += 1
        numbers[(pos - 1 + 1) % 4] += 1

    def divide_adjacent(pos):
        add_operation('/', pos)
        numbers[pos - 1] //= 2
        numbers[(pos - 1 + 1) % 4] //= 2

    def is_all_one():
